package com.resumethinking.platform.matching;
import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class JpaCallbackReceiptRepository implements CallbackReceiptRepository { private final CallbackReceiptJpaRepository delegate; public JpaCallbackReceiptRepository(CallbackReceiptJpaRepository delegate){this.delegate=delegate;} public Optional<CallbackReceipt> findByCallbackId(String id){return delegate.findById(id).map(CallbackReceiptEntity::toRecord);} public CallbackReceipt save(CallbackReceipt r){return delegate.save(new CallbackReceiptEntity(r)).toRecord();} public CallbackReceipt saveAndFlush(CallbackReceipt r){return delegate.saveAndFlush(new CallbackReceiptEntity(r)).toRecord();} }
